insert into public.investment_structure_profiles(investment_id,model_version,capital_protection,liquidity_level,price_volatility,income_predictability,growth_participation,interest_rate_sensitivity,credit_exposure,diversification_level,complexity_level,time_structure,principal_protection_basis,source_basis,as_of_date)
select i.id,'structure-v1',x.capital_protection,x.liquidity_level,x.price_volatility,x.income_predictability,x.growth_participation,x.interest_rate_sensitivity,x.credit_exposure,x.diversification_level,x.complexity_level,x.time_structure,x.principal_protection_basis,x.source_basis::jsonb,x.as_of_date
from (values
 ('RBC-GIC-1Y-NR','insured_deposit','locked','none','very_high','none','low','Royal Bank of Canada deposit','single_issuer','low','locked_term','Principal is repayable at maturity; eligible deposits at CDIC member institutions may be protected within applicable CDIC category limits','{"product_source":"RBC","insurance_source":"CDIC"}','2026-09-11'::date),
 ('RBC-GIC-5Y-NR','insured_deposit','locked','none','very_high','none','low','Royal Bank of Canada deposit','single_issuer','low','locked_term','Principal is repayable at maturity; eligible deposits at CDIC member institutions may be protected within applicable CDIC category limits','{"product_source":"RBC","insurance_source":"CDIC"}','2026-09-11'::date),
 ('RBC-GIC-1Y-CASH','insured_deposit','medium','none','high','none','low','Royal Bank of Canada deposit','single_issuer','low','locked_term','Principal is contractual; early access is subject to cashable-product rules and eligible deposits may be protected within applicable CDIC category limits','{"product_source":"RBC","insurance_source":"CDIC"}','2026-09-11'::date),
 ('RBC-GIC-3Y-RED','insured_deposit','medium','none','high','none','low','Royal Bank of Canada deposit','single_issuer','low','locked_term','Principal is contractual; redemption before maturity can reduce the rate received and eligible deposits may be protected within applicable CDIC category limits','{"product_source":"RBC","insurance_source":"CDIC"}','2026-09-11'::date),
 ('GOC-TBILL-3M','contractual','high','very_low','high','none','low','Government of Canada','single_issuer','low','short_term','Government of Canada obligation; market value can vary before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-TBILL-6M','contractual','high','very_low','high','none','low','Government of Canada','single_issuer','low','short_term','Government of Canada obligation; market value can vary before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-TBILL-1Y','contractual','high','very_low','high','none','low','Government of Canada','single_issuer','low','short_term','Government of Canada obligation; market value can vary before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-BOND-2Y','contractual','high','low','high','none','low','Government of Canada','single_issuer','low','fixed_maturity','Government of Canada obligation; price can move before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-BOND-5Y','contractual','high','medium','high','none','medium','Government of Canada','single_issuer','low','fixed_maturity','Government of Canada obligation; price can move before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-BOND-10Y','contractual','high','medium','high','none','high','Government of Canada','single_issuer','low','fixed_maturity','Government of Canada obligation; longer duration can create larger price changes before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('GOC-BOND-LONG','contractual','high','high','high','none','high','Government of Canada','single_issuer','low','fixed_maturity','Government of Canada obligation; long duration can create substantial price sensitivity before maturity','{"source":"Bank of Canada"}','2026-09-14'::date),
 ('ON-BOND-2031','conditional','medium','medium','high','none','medium','Province of Ontario','single_issuer','low','fixed_maturity','Repayment depends on the provincial issuer meeting its obligations; secondary-market value can vary','{"source":"Ontario Financing Authority"}','2026-09-15'::date),
 ('BELL-M69-2036','conditional','medium','medium','high','none','high','Bell Canada / BCE corporate credit','single_issuer','medium','fixed_maturity','Repayment depends on the corporate issuer/guarantor meeting its obligations; secondary-market value can vary','{"source":"Bell Canada"}','2026-09-15'::date),
 ('CA-CP-REF','conditional','medium','very_low','high','none','low','Short-term corporate issuer credit','single_issuer','medium','short_term','No deposit insurance; repayment depends on the issuing company and specific paper','{"source":"Bank of Canada educational reference"}','2026-09-15'::date),
 ('CA-ABCP-REF','conditional','medium','low','high','none','low','Asset pool plus program liquidity/credit support','limited','high','short_term','No deposit insurance; repayment depends on the securitized asset/program structure and support arrangements','{"source":"Canadian Fixed-Income Forum / Bank of Canada educational reference"}','2026-09-15'::date)
) as x(symbol,capital_protection,liquidity_level,price_volatility,income_predictability,growth_participation,interest_rate_sensitivity,credit_exposure,diversification_level,complexity_level,time_structure,principal_protection_basis,source_basis,as_of_date)
join public.investments i on i.symbol=x.symbol
on conflict (investment_id,model_version) do update set
 capital_protection=excluded.capital_protection,liquidity_level=excluded.liquidity_level,price_volatility=excluded.price_volatility,income_predictability=excluded.income_predictability,growth_participation=excluded.growth_participation,interest_rate_sensitivity=excluded.interest_rate_sensitivity,credit_exposure=excluded.credit_exposure,diversification_level=excluded.diversification_level,complexity_level=excluded.complexity_level,time_structure=excluded.time_structure,principal_protection_basis=excluded.principal_protection_basis,source_basis=excluded.source_basis,as_of_date=excluded.as_of_date,updated_at=now();

insert into public.investment_deposit_terms(investment_id,annual_rate_pct,term_months,redeemability,minimum_deposit,interest_payment_frequency,registered_account_eligibility,deposit_insurance_scheme,deposit_insurance_eligible,lockup_note,source_name,source_url,as_of_date)
select i.id,x.annual_rate_pct,x.term_months,x.redeemability,null,x.payment_frequency,'{}'::text[],'CDIC',true,x.lockup_note,'RBC Royal Bank','https://www.rbcroyalbank.com/services/gic-rates/special/index-1.html','2026-09-11'::date
from (values
 ('RBC-GIC-1Y-NR',2.45::numeric,12,'non_redeemable','At maturity or according to the selected interest-payment option.','Not redeemable before maturity under the standard non-redeemable terms.'),
 ('RBC-GIC-5Y-NR',2.75::numeric,60,'non_redeemable','Annually, semi-annually or at maturity depending on the selected option.','Not redeemable before maturity under the standard non-redeemable terms.'),
 ('RBC-GIC-1Y-CASH',1.95::numeric,12,'redeemable','Semi-annually or at maturity.','Cashable subject to product rules; early redemption rates can differ from the headline rate.'),
 ('RBC-GIC-3Y-RED',2.45::numeric,36,'redeemable','Annually, semi-annually or at maturity depending on the selected option.','Redeemable, but prior-redemption rates are lower than the full-term posted rate.')
) as x(symbol,annual_rate_pct,term_months,redeemability,payment_frequency,lockup_note)
join public.investments i on i.symbol=x.symbol
on conflict (investment_id,term_months,redeemability,as_of_date) do update set annual_rate_pct=excluded.annual_rate_pct,interest_payment_frequency=excluded.interest_payment_frequency,deposit_insurance_scheme=excluded.deposit_insurance_scheme,deposit_insurance_eligible=excluded.deposit_insurance_eligible,lockup_note=excluded.lockup_note,source_name=excluded.source_name,source_url=excluded.source_url;

