insert into public.investment_structure_profiles(investment_id,model_version,capital_protection,liquidity_level,price_volatility,income_predictability,growth_participation,interest_rate_sensitivity,credit_exposure,diversification_level,complexity_level,time_structure,principal_protection_basis,source_basis,as_of_date)
select d.investment_id,'structure-v1','none','high',
 case coalesce(d.official_risk_rating,d.risk_band)
  when 'Low' then 'low' when 'Low to Medium' then 'low' when 'Medium' then 'medium' when 'Medium to High' then 'high' when 'High' then 'very_high' else null end,
 case when d.income_score is null then null when d.income_score<20 then 'low' when d.income_score<60 then 'medium' else 'high' end,
 case when d.growth_score is null then null when d.growth_score<40 then 'low' when d.growth_score<75 then 'medium' else 'high' end,
 case when coalesce(d.fixed_income_pct,0)>=50 then 'medium' else 'not_applicable' end,
 'Diversified fund holdings','diversified','medium','open_ended','No contractual principal protection; market value fluctuates',jsonb_build_object('derived_from','v_investment_dna_v2','model',d.intelligence_model_version),greatest(d.as_of_date,current_date-1)
from public.v_investment_dna_v2 d
where d.asset_type='ETF'
on conflict (investment_id,model_version) do update set capital_protection=excluded.capital_protection,liquidity_level=excluded.liquidity_level,price_volatility=excluded.price_volatility,income_predictability=excluded.income_predictability,growth_participation=excluded.growth_participation,interest_rate_sensitivity=excluded.interest_rate_sensitivity,credit_exposure=excluded.credit_exposure,diversification_level=excluded.diversification_level,complexity_level=excluded.complexity_level,time_structure=excluded.time_structure,principal_protection_basis=excluded.principal_protection_basis,source_basis=excluded.source_basis,as_of_date=excluded.as_of_date,updated_at=now();
